const $=s=>document.querySelector(s);
function dateText(v,opts={}){if(!v)return '-';const d=new Date(v);if(Number.isNaN(d.getTime()))return String(v);const tz=state?.settings?.timezone||'Asia/Riyadh';const parts=new Intl.DateTimeFormat('ar-SA',{timeZone:tz,day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:true,...opts}).formatToParts(d);const get=k=>parts.find(x=>x.type===k)?.value||'';return `${get('day')}/${get('month')}/${get('year')} — ${get('hour')}:${get('minute')} ${get('dayPeriod')}`;}
function dateOnly(v){return dateText(v,{hour:undefined,minute:undefined,hour12:undefined});}
const state={me:null,cats:[],yards:[],settings:null,tab:'home',owners:[],customerPreview:false};
const __apiInFlight=new Map(),__apiRecent=new Map();
const OFFLINE_KEY='houshakOfflineQueueV1', SNAP_KEY='houshakOfflineSnapshotV1';
function offlineQueue(){try{return JSON.parse(localStorage.getItem(OFFLINE_KEY)||'[]')}catch{return []}}
function setOfflineQueue(q){localStorage.setItem(OFFLINE_KEY,JSON.stringify(q));updateOfflineIndicator()}
function queueOfflineOperation(op){const q=offlineQueue();if(!q.some(x=>x.id===op.id))q.push(op);setOfflineQueue(q)}
const OFFLINE_DB='houshak-offline-v1';
function offlineStore(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window))return resolve(null);const req=indexedDB.open(OFFLINE_DB,1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('operations'))db.createObjectStore('operations',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function offlinePut(op){try{const db=await offlineStore();if(!db)return false;await new Promise((resolve,reject)=>{const tx=db.transaction('operations','readwrite');tx.objectStore('operations').put(op);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});return true}catch{return false}}
async function offlineGet(id){try{const db=await offlineStore();if(!db)return null;return await new Promise((resolve,reject)=>{const tx=db.transaction('operations','readonly');const r=tx.objectStore('operations').get(id);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)})}catch{return null}}
async function offlineDelete(id){try{const db=await offlineStore();if(!db)return;await new Promise((resolve,reject)=>{const tx=db.transaction('operations','readwrite');tx.objectStore('operations').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}catch{}}
async function queueOfflineOperationAsync(op){queueOfflineOperation({...op,payload:{...op.payload}});await offlinePut(op)}
function updateOfflineIndicator(){let el=document.querySelector('.offline-indicator');if(!el){el=document.createElement('div');el.className='offline-indicator';document.body.appendChild(el)}const n=offlineQueue().length;el.textContent=!navigator.onLine?`🟠 بدون إنترنت${n?` — ${n} عملية بانتظار المزامنة`:''}`:n?`🟡 مزامنة ${n} عملية...`:'🟢 متصل';el.classList.toggle('offline',!navigator.onLine);el.classList.toggle('pending',navigator.onLine&&n>0)}
async function flushOfflineQueue(){if(!navigator.onLine)return;const q=offlineQueue();if(!q.length){updateOfflineIndicator();return}for(const op of q.slice()){try{const stored=await offlineGet(op.id);const operation=stored||op;const images=Array.isArray(operation.images)?operation.images:[];const payload={...operation.payload};delete payload.images;const r=await fetch('/api/admin/offline-sync',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operations:[{...operation,payload}]})});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'تعذر مزامنة العملية');const synced=d.results?.[0]?.asset;if(synced?.id&&images.length){for(const dataUrl of images){const ir=await fetch('/api/admin/assets/'+synced.id+'/images',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataUrl})});if(!ir.ok)throw Error('تعذر رفع إحدى صور الأصل بعد عودة الإنترنت')}}setOfflineQueue(offlineQueue().filter(x=>x.id!==op.id));await offlineDelete(op.id)}catch(e){console.warn('offline sync paused',e);break}}updateOfflineIndicator()}
async function api(url,opt={}){const method=String(opt.method||'GET').toUpperCase();const body=opt.body||'';const key=(method==='POST'||method==='PUT'||method==='PATCH')?`${method} ${url} ${body}`:null;if(key){const existing=__apiInFlight.get(key)||__apiRecent.get(key);if(existing)return existing;const run=(async()=>{const r=await fetch(url,{headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'حدث خطأ');return d})();__apiInFlight.set(key,run);const cleanup=()=>{__apiInFlight.delete(key);__apiRecent.set(key,run);setTimeout(()=>{if(__apiRecent.get(key)===run)__apiRecent.delete(key)},2000)};run.then(cleanup,cleanup);return run}try{const r=await fetch(url,{headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'حدث خطأ');return d}catch(e){if(method==='GET'&&(!navigator.onLine||e instanceof TypeError)){const snap=snapshot();if(url==='/api/categories'&&snap.cats)return snap.cats;if(url==='/api/yards'&&snap.yards)return snap.yards;if(url==='/api/public/settings'&&snap.settings)return snap.settings;if(url==='/api/auth/me'&&snap.me)return {user:snap.me};if(url.startsWith('/api/admin/owners'))return snap.owners||[];if(url==='/api/vehicle-types')return snap.vehicleTypes||[]}throw e}}
window.addEventListener('online',()=>{updateOfflineIndicator();flushOfflineQueue()});window.addEventListener('offline',updateOfflineIndicator);setTimeout(updateOfflineIndicator,0);
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('ar-SA');
const purposeName=p=>({STORAGE:'توقيف',SALE:'بيع',RENT:'إيجار',SALE_RENT:'بيع وإيجار'})[p]||p;
const statusName=s=>({ACTIVE:'نشط',RESERVED:'محجوز',SOLD:'مباع',RENTED:'مؤجر',EXITED:'خارج الحوش'})[s]||s;
const identityName=s=>({NATIONAL_ID:'هوية وطنية',PERSONAL_ID:'بطاقة شخصية',RESIDENCY_ID:'هوية مقيم',PASSPORT:'جواز سفر',OTHER:'هوية أخرى'})[s]||s;
const actionName=s=>({CREATE:'إنشاء',UPDATE:'تعديل',DELETE:'حذف',CONFIRM:'تأكيد',CANCEL:'إلغاء',PAYMENT:'تسجيل دفعة',RESERVE:'حجز',EXIT:'إخراج',REJECT:'رفض',ACCEPT:'قبول'})[s]||s;
const entityName=s=>({ASSET:'أصل',OWNER:'مالك',USER:'مستخدم',RESERVATION:'حجز',OFFER:'عرض',ORDER:'طلب',TRANSACTION:'حركة مالية',INVOICE:'فاتورة',CONTRACT:'عقد',LOCATION:'موقع داخل الحوش',CONDITION:'محضر استلام/تسليم',CATEGORY:'تصنيف',VEHICLE_TYPE:'نوع مركبة',INQUIRY:'استفسار',RECEIPT:'سند',SETTINGS:'إعدادات النظام'})[s]||s;
const statusArabic=s=>({PENDING:'قيد المراجعة',CONFIRMED:'مؤكد',REJECTED:'مرفوض',CANCELLED:'ملغى',COMPLETED:'مكتمل',ACCEPTED:'مقبول',NEW:'جديد',IN_PROGRESS:'قيد التنفيذ',DRAFT:'مسودة',ISSUED:'صادرة',PAID:'مدفوعة',PARTIAL:'مدفوعة جزئيًا'})[s]||s;
function auditDetails(d){if(!d||typeof d!=='object')return '';const labels={status:'الحالة',depositAmount:'العربون',agreedAmount:'المبلغ المتفق عليه',amount:'المبلغ',type:'النوع',assetId:'الأصل',partyName:'الطرف',partyPhone:'الجوال',commissionType:'نوع العمولة',commissionRate:'نسبة العمولة',commissionFixed:'العمولة الثابتة',condition:'حالة الأصل',odometer:'عداد الكيلومترات',engineHours:'ساعات التشغيل',notes:'الملاحظات',description:'البيان',category:'التصنيف',reference:'المرجع'};return Object.entries(d).map(([k,v])=>{if(v===null||v===undefined||v==='')return '';let val=v;if(k==='status'||k==='type')val=statusArabic(v)||v;return `<div><b>${esc(labels[k]||k)}</b>: ${esc(String(val))}</div>`}).filter(Boolean).join('')}
function money(n){return `${fmt(n)} ${esc(state.settings?.currencySymbol||'ر.س')}`}
function waNumber(){let n=String(state.settings?.whatsapp||'').replace(/\D/g,'');if(n.startsWith('00'))n=n.slice(2);if(n.startsWith('0'))n=String(state.settings?.countryCode||'966')+n.slice(1);return n}
function contactNumber(value){return String(value||'').replace(/[^0-9+]/g,'')}
function contactWaNumber(value){let n=contactNumber(value).replace(/^\+/, '');if(n.startsWith('00'))n=n.slice(2);if(n.startsWith('0'))n=String(state.settings?.countryCode||'966')+n.slice(1);return n}
let deferredInstallPrompt=null; window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;setTimeout(showInstallPrompt,900)}); window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;document.querySelector('.install-prompt')?.remove()}); function showInstallPrompt(){if(!deferredInstallPrompt||window.matchMedia('(display-mode: standalone)').matches||document.querySelector('.install-prompt'))return;const admin=location.pathname.startsWith('/admin');const name=admin?'حوشك إدارة':'حوشك';const el=document.createElement('div');el.className='install-prompt';el.innerHTML=`<div><strong>ثبّت ${name}</strong><small>أضف المنصة إلى شاشة هاتفك لتفتح مثل التطبيق.</small></div><button class="btn primary" onclick="installHoushak()">تثبيت</button><button class="install-close" onclick="this.parentElement.remove()" aria-label="إغلاق">×</button>`;document.body.appendChild(el)} async function installHoushak(){if(!deferredInstallPrompt)return;deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;document.querySelector('.install-prompt')?.remove()}
async function init(){const snap=snapshot();try{state.me=(await api('/api/auth/me')).user;try{localStorage.setItem('houshakOfflineSnapshotV1',JSON.stringify({...snap,me:state.me}))}catch{}}catch{state.me=snap.me||null}try{state.cats=await api('/api/categories')}catch{state.cats=snap.cats||[]}try{state.yards=await api('/api/yards')}catch{state.yards=snap.yards||[]}try{state.settings=await api('/api/public/settings')}catch{state.settings=snap.settings||{name:'حوشك',tagline:'منصة إدارة الأصول'}}const admin=location.pathname.startsWith('/admin');if(admin&&state.me){try{state.owners=await api('/api/admin/owners?q=')}catch{state.owners=snap.owners||[]}}try{window.__vehicleTypes=await api('/api/vehicle-types');saveSnapshot()}catch{window.__vehicleTypes=snap.vehicleTypes||[]}document.title=admin?`${state.settings.name} إدارة`:state.settings.name;state.customerPreview=new URLSearchParams(location.search).get('customerPreview')==='1';updateOfflineIndicator();flushOfflineQueue();if(admin){history.replaceState({view:'exit-guard',admin:true},'',location.pathname+location.search);history.pushState({view:'admin-home'},'',location.pathname+location.search);return adminPortal()}history.replaceState({view:'exit-guard',admin:false},'',location.pathname+location.search);history.pushState({view:'home',customerPreview:state.customerPreview},'',location.pathname+location.search);await home(true)}
function navigate(view,href){history.pushState(view,'',href||location.pathname);return view}
function goBack(){if(document.querySelector('.modal')){closeModal();return}if(history.state?.view&&history.state.view!=='home'){history.back();return}if(confirm('هل أنت متأكد من الخروج؟')){window.__allowExit=true;history.back()}}
window.addEventListener('popstate',async e=>{if(document.querySelector('.modal')){closeModal();history.pushState(e.state||{view:'home'},'',location.href);return}const s=e.state;try{if(s?.view==='detail'&&s.id)return detail(s.id,true);if(s?.view==='about')return aboutPage(true);if(s?.view==='listings')return listings(s.purpose||'',s.cat||'',true);if(s?.view==='dashboard')return dashboard(s.tab||'overview',true);if(s?.view==='home')return home(true);if(s?.view==='admin-home')return dashboard('overview',true);if(s?.view==='exit-guard'||!s){if(confirm('هل أنت متأكد من الخروج من التطبيق؟')){window.__allowExit=true;history.back()}else{window.__allowExit=false;if(s?.admin){history.pushState({view:'admin-home'},'',location.pathname+location.search);return dashboard('overview',true)}history.pushState({view:'home',customerPreview:state.customerPreview},'',location.pathname+location.search)}}}catch(err){console.error(err);home(true)}})
function tickerHtml(s){const xs=Array.isArray(s.tickerMessages)?s.tickerMessages.filter(Boolean):[];return xs.length?`<section class="ticker" aria-label="رسائل حوشك"><div class="ticker-track">${xs.map((x,i)=>`<span class="ticker-item">${i?'• ':''}${esc(x)}</span>`).join('')}</div></section>`:''}
function locationButton(s){const lat=String(s?.latitude||'').trim(),lng=String(s?.longitude||'').trim(),url=String(s?.mapsUrl||'').trim();const q=lat&&lng?encodeURIComponent(`${lat},${lng}`):encodeURIComponent(s?.address||[s?.country,s?.city].filter(Boolean).join('، ')||'حوشك');const href=url||`https://www.google.com/maps/search/?api=1&query=${q}`;return `<div class="location-cta"><span>📍 ${esc(s?.address||'موقع الحوش')}</span><a class="btn" target="_blank" rel="noopener noreferrer" href="${esc(href)}">الوصول إلى موقع الحوش</a></div>`}
function shell(content){const s=state.settings||{name:'النظام'};return `<header class="top"><div class="nav"><div><div class="brand">${esc(s.name)}</div><small>${esc(s.tagline||'')}</small></div><div class="navlinks"><button onclick="home()">الرئيسية</button><button onclick="listings('SALE')">للبيع</button><button onclick="listings('RENT')">للإيجار</button><button onclick="listings()">المعروض</button></div></div></header>${tickerHtml(s)}${content}<footer class="footer"><div><strong>${esc(s.name)}</strong> — ${esc(s.tagline||'نظام إدارة الأصول')}</div><button class="btn footer-about-btn" onclick="aboutPage()">عن حوشك</button><div class="footer-credit">مالك الحوش: ${esc(s.ownerName||'أبو مناحي السبيعي')} · مدير الحوش: ${esc(s.managerName||'أبو أنس الإدريسي')} · تطوير وبرمجة: ${esc(s.developerName||'هيثم القاضي')} · © ${new Date().getFullYear()} ${esc(s.name)} — جميع الحقوق محفوظة</div><div class="footer-credit">${s.ownerPhone?`مالك الحوش: <a href="tel:${esc(contactNumber(s.ownerPhone))}">${esc(s.ownerPhone)}</a>`:''}${s.managerPhone?` · مدير الحوش: <a href="tel:${esc(contactNumber(s.managerPhone))}">${esc(s.managerPhone)}</a>`:''}</div>${locationButton(s)}</footer>`}
function adminShell(content){const s=state.settings||{name:'النظام'};return `<header class="top admin-top"><div class="nav"><div><div class="brand">${esc(s.name)} — الإدارة</div><small>لوحة التحكم الداخلية</small></div><div class="navlinks"><button onclick="dashboard('overview')">الرئيسية</button><button onclick="customerPreview()">👁️ معاينة كعميل</button><button onclick="home()">المنصة العامة</button><button onclick="logout()">خروج</button></div></div></header>${content}<footer class="footer">${esc(s.name)} — لوحة الإدارة الداخلية</footer>`}
async function adminPortal(){document.body.classList.add('admin-mode');if(!state.me){return adminLogin()}if(!['ADMIN','MANAGER','SALES','ACCOUNTING','RECEPTION'].includes(state.me.role)){await api('/api/auth/logout',{method:'POST'}).catch(()=>{});state.me=null;return adminLogin('لا تملك صلاحية الدخول إلى لوحة الإدارة')}await dashboard('overview',true)}
function customerPreview(){location.href='/?customerPreview=1'}
function adminLogin(error=''){document.body.classList.add('admin-mode');document.querySelector('#app').innerHTML=`<div class="admin-login-wrap"><section class="panel admin-login"><div class="brand admin-login-brand">${esc(state.settings?.name||'حوشك')} — الإدارة</div><p class="muted">دخول الموظفين والإدارة فقط</p>${error?`<div class="notice danger">${esc(error)}</div>`:''}<div class="field"><label>الجوال</label><input id="lp" class="input"></div><div class="field"><label>كلمة المرور</label><input id="lx" class="input" type="password"></div><button class="btn primary" onclick="adminLoginSubmit()">دخول لوحة الإدارة</button><button class="btn" onclick="location.href='/'">العودة للمنصة</button></section></div>`}
async function adminLoginSubmit(){try{await api('/api/auth/login',{method:'POST',body:JSON.stringify({phone:$('#lp').value,password:$('#lx').value})});state.me=(await api('/api/auth/me')).user;location.href='/admin'}catch(e){adminLogin(e.message)}}
async function aboutPage(fromHistory=false){const s=state.settings||await api('/api/public/settings');document.querySelector('#app').innerHTML=shell(`<main class="container about-page"><div class="page-head"><button class="btn" onclick="goBack()">← رجوع</button><div><h1>${esc(s.aboutTitle||'عن حوشك')}</h1><p class="muted">تعرف على المنصة والحوش والخدمات وطريقة الاستخدام.</p></div></div><section class="about-hero panel"><div class="about-mark">🏠</div><div><h2>${esc(s.name)}</h2><p>${esc(s.aboutText||'')}</p></div></section><section class="about-grid"><article class="panel"><h3>ماذا نقدم؟</h3><p>${esc(s.servicesText||'')}</p></article><article class="panel"><h3>كيف تستخدم حوشك؟</h3><p>${esc(s.howToText||'')}</p></article><article class="panel"><h3>رؤيتنا والتطوير المستمر</h3><p>${esc(s.futureText||'')}</p></article><article class="panel"><h3>عن الحوش</h3><p>مالك الحوش: <strong>${esc(s.ownerName||'أبو مناحي السبيعي')}</strong></p><p>مدير الحوش: <strong>${esc(s.managerName||'أبو أنس الإدريسي')}</strong></p>${s.ownerPhone?`<p>رقم المالك: <a href="tel:${esc(contactNumber(s.ownerPhone))}">${esc(s.ownerPhone)}</a></p>`:''}${s.managerPhone?`<p>رقم المدير: <a href="tel:${esc(contactNumber(s.managerPhone))}">${esc(s.managerPhone)}</a></p>`:''}<p class="muted">يمكنك الاستفسار عن أي أصل أو خدمة من صفحة التفاصيل أو عبر وسائل التواصل المتاحة في المنصة.</p></article></section><section class="panel location-panel"><h3>📍 موقع الحوش</h3><p>${esc(s.address||'يمكنك فتح موقع الحوش مباشرة على الخريطة.')}</p>${locationButton(s)}</section><section class="panel contact-panel"><h3>هل لديك استفسار؟</h3><p>ما عليك إلا اختيار الأصل أو الخدمة ثم إرسال استفسارك من خلال صفحة التفاصيل، أو استخدام وسيلة التواصل المتاحة في المنصة.</p>${s.whatsapp?`<a class="btn success" target="_blank" rel="noopener" href="https://wa.me/${esc(waNumber())}">التواصل عبر واتساب</a>`:''}</section></main>`);if(!fromHistory)navigate({view:'about'},'#about')}
async function home(fromHistory=false){const featured=await api('/api/listings?limit=8');const shown=featured.slice(0,8);document.querySelector('#app').innerHTML=shell(`<main class="container"><section class="hero"><h1>إدارة الأصول والحوش في نظام واحد</h1><p>توقيف، بيع، إيجار، وساطة، تخزين، حجوزات، عروض، مالية، فواتير، وعقود.</p><div class="toolbar"><button class="btn primary" onclick="listings()">تصفح المعروض</button>${state.me&&!state.customerPreview?`<button class="btn" onclick="dashboard()">فتح لوحة الإدارة</button>`:''}</div></section><section class="panel"><div class="section-head"><div><h2>أبرز المعروض</h2><p class="muted">سيارات، سطحات، دينات، معدات وغيرها — اختر ما يناسبك.</p></div><button class="btn" onclick="listings()">عرض الكل</button></div>${cards(shown,true)}</section><section class="panel"><div class="section-head"><h2>تصفح حسب التصنيف</h2><button class="btn" onclick="listings()">كل المعروض</button></div><div class="category-grid">${state.cats.map(c=>`<button class="category-tile" onclick="listings('', '${c.id}')"><span class="category-icon">${c.icon||'📦'}</span><strong>${esc(c.name)}</strong><small>${c.allowSale&&c.allowRent?'بيع وإيجار':c.allowSale?'للبيع':c.allowRent?'للإيجار':'توقيف'}</small></button>`).join('')}</div></section></main>`)}
async function listings(purpose='',cat='',fromBack=false){const qs=new URLSearchParams();if(purpose)qs.set('purpose',purpose);if(cat)qs.set('categoryId',cat);const xs=await api('/api/listings?'+qs);const category=state.cats.find(c=>c.id===cat);const title=category?.name||purposeName(purpose)||'كل المعروض';const isSpecific=!!cat;document.querySelector('#app').innerHTML=shell(`<main class="container"><div class="page-head"><button class="btn" onclick="goBackToPublic('${purpose||''}','${cat||''}')">← رجوع</button><div><h2>${esc(title)}</h2>${isSpecific?'<p class="muted">المعروض من هذا التصنيف فقط.</p>':''}</div></div>${isSpecific?'':`<div class="search"><input id="q" class="input" placeholder="بحث بالاسم أو الكود أو المالك أو الموقع"><select id="cat" class="select"><option value="">كل التصنيفات</option>${state.cats.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><input id="min" class="input" type="number" placeholder="أقل سعر"><input id="max" class="input" type="number" placeholder="أعلى سعر"><button class="btn primary" onclick="doSearch('${purpose||''}')">بحث</button></div>`}<div id="results">${cards(xs)}</div></main>`);if(!fromBack)navigate({view:'listings',purpose,cat},`#listings${cat?'-'+cat:''}${purpose?'-'+purpose.toLowerCase():''}`)}
function goBackToPublic(purpose,cat){goBack()}

function cards(xs,market=false){return xs.length?`<div class="${market?'market-grid':'grid'}">${xs.map(a=>`<article class="card market-card"><div class="image-wrap gallery-cover" onclick="detail('${a.id}')">${a.images?.[0]?`<img src="${a.images[0].url}" alt="${esc(a.title)}">`:`<div class="image-placeholder">${a.category?.icon||'📦'}</div>`}${a.images?.length?`<span class="image-count">📷 ${a.images.length} صورة</span>`:''}<span class="offer-badge">${purposeName(a.purpose)}</span></div><div class="body"><h3>${esc(a.title)}</h3><p class="muted">${esc([a.model,a.color].filter(Boolean).join(' · '))}</p>${a.salePrice?`<div class="price">السعر المطلوب: ${money(a.salePrice)}</div>`:''}${a.currentBid?`<div class="price">السوم الحالي: ${money(a.currentBid)}</div>`:''}${a.rentPrice?`<div class="price">${money(a.rentPrice)} / ${esc(a.rentUnit)}</div>`:''}<p class="muted">${esc(a.category?.name||'')} · ${esc(a.yard?.city||'')}</p><button class="btn primary" onclick="detail('${a.id}')">التفاصيل</button></div></article>`).join('')}</div>`:'<div class="empty">لا توجد نتائج.</div>'}
async function doSearch(purpose){const qs=new URLSearchParams();if(purpose)qs.set('purpose',purpose);if($('#q').value)qs.set('q',$('#q').value);if($('#cat').value)qs.set('categoryId',$('#cat').value);if($('#min').value)qs.set('minPrice',$('#min').value);if($('#max').value)qs.set('maxPrice',$('#max').value);$('#results').innerHTML=cards(await api('/api/listings?'+qs))}
async function openImageGallery(id,index=0){try{const a=await api('/api/listings/'+id);const imgs=a.images||[];if(!imgs.length)return;const i=Math.max(0,Math.min(Number(index)||0,imgs.length-1));window.__gallery={id,index:i,images:imgs,title:a.title};const img=imgs[i];modal(`<div class="lightbox"><div class="lightbox-head"><strong>${esc(a.title)}</strong><span>${i+1} / ${imgs.length}</span></div><img class="lightbox-image" src="${img.url}" alt="${esc(a.title)} — صورة ${i+1}"><div class="lightbox-actions"><button class="btn" onclick="galleryMove('${a.id}',${i-1})" ${i===0?'disabled':''}>→ السابقة</button><button class="btn primary" onclick="closeModal()">إغلاق</button><button class="btn" onclick="galleryMove('${a.id}',${i+1})" ${i===imgs.length-1?'disabled':''}>التالية ←</button></div></div>`)}catch(e){alert(e.message)}}
async function galleryMove(id,index){const g=window.__gallery;if(!g||g.id!==id)return openImageGallery(id,index);if(index<0||index>=g.images.length)return;g.index=index;const img=g.images[index];modal(`<div class="lightbox"><div class="lightbox-head"><strong>${esc(g.title||state.settings?.name||'حوشك')}</strong><span>${index+1} / ${g.images.length}</span></div><img class="lightbox-image" src="${img.url}" alt="صورة ${index+1}"><div class="lightbox-actions"><button class="btn" onclick="galleryMove('${id}',${index-1})" ${index===0?'disabled':''}>→ السابقة</button><button class="btn primary" onclick="closeModal()">إغلاق</button><button class="btn" onclick="galleryMove('${id}',${index+1})" ${index===g.images.length-1?'disabled':''}>التالية ←</button></div></div>`)}
async function detail(id,fromHistory=false){const a=await api('/api/listings/'+id);document.querySelector('#app').innerHTML=shell(`<main class="container"><button class="btn" onclick="history.back();setTimeout(()=>{if(!document.querySelector('#results'))home()},50)">← رجوع</button><div class="panel"><div class="gallery">${(a.images||[]).map((i,n)=>`<button class="gallery-thumb" onclick="openImageGallery('${a.id}',${n})" type="button"><img src="${i.url}" alt="${esc(a.title)} — صورة ${n+1}"><span>${n+1}</span></button>`).join('')||'<div class="empty">لا توجد صور</div>'}</div><h2>${esc(a.title)}</h2><span class="pill">${purposeName(a.purpose)}</span><p>${esc(a.description)}</p><div class="three"><div><b>التصنيف</b><br>${esc(a.category?.name)}</div><div><b>الموقع</b><br>${esc(a.yard?.city)}</div><div><b>الكود</b><br>${esc(a.code)}</div></div><p>${esc([a.model,a.color,a.variant].filter(Boolean).join(' · '))}</p>${a.salePrice?`<div class="price">السعر المطلوب: ${money(a.salePrice)}</div>`:''}${a.currentBid?`<div class="price">السوم الحالي: ${money(a.currentBid)}</div>`:''}${a.rentPrice?`<div class="price">${money(a.rentPrice)} / ${esc(a.rentUnit)}</div>`:''}<div class="toolbar"><a class="btn success" target="_blank" href="https://wa.me/${esc(waNumber())}?text=${encodeURIComponent('استفسار عن الإعلان '+a.code+' - '+a.title)}">واتساب</a><button class="btn primary" onclick="inquiry('${a.id}','${esc(a.title)}')">استفسار</button>${['RENT','SALE','SALE_RENT'].includes(a.purpose)?`<button class="btn" onclick="reserve('${a.id}')">طلب حجز</button>`:''}${['SALE','SALE_RENT'].includes(a.purpose)?`<button class="btn" onclick="offer('${a.id}')">تقديم عرض</button>`:''}</div></div></main>`);if(!fromHistory)navigate({view:'detail',id},`#detail-${id}`)}
function modal(html){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div>${html}<div class="toolbar"><button class="btn" onclick="closeModal()">إغلاق</button></div></div>`;document.body.appendChild(m)}function closeModal(){document.querySelector('.modal')?.remove()}
function loginModal(){modal(`<h3>دخول الإدارة</h3><div class="field"><label>الجوال</label><input id="lp" class="input" value="0500000000"></div><div class="field"><label>كلمة المرور</label><input id="lx" class="input" type="password" value="Admin@12345"></div><button class="btn primary" onclick="login()">دخول</button>`)}
async function login(){try{await api('/api/auth/login',{method:'POST',body:JSON.stringify({phone:$('#lp').value,password:$('#lx').value})});state.me=(await api('/api/auth/me')).user;closeModal();location.href='/admin'}catch(e){alert(e.message)}}
function vehicleTypeForm(v={}){modal(`<h3>${v.id?'تعديل نوع مركبة':'إضافة نوع مركبة'}</h3><div class="field"><label>اسم النوع</label><input id="vtn" class="input" value="${esc(v.name||'')}" placeholder="مثال: سيدان"></div><label class="checkline"><input id="vta" type="checkbox" ${v.active!==false?'checked':''}> نشط</label><br><button class="btn primary" onclick="saveVehicleType('${v.id||''}')">حفظ</button>`)}
async function saveVehicleType(id){try{await api(id?'/api/admin/vehicle-types/'+id:'/api/admin/vehicle-types',{method:id?'PUT':'POST',body:JSON.stringify({name:$('#vtn').value,active:$('#vta').checked})});closeModal();dashboard('vehicleTypes')}catch(e){alert(e.message)}}
async function deleteVehicleType(id){if(!confirm('سيتم حذف النوع إذا لم يكن مرتبطًا بأصل، وإلا سيتم تعطيله. هل تريد المتابعة؟'))return;try{await api('/api/admin/vehicle-types/'+id,{method:'DELETE'});dashboard('vehicleTypes')}catch(e){alert(e.message)}}
async function logout(){if(!confirm('هل أنت متأكد من الخروج النهائي من التطبيق؟'))return;try{await api('/api/auth/logout',{method:'POST'});state.me=null;try{localStorage.removeItem('houshakAuth');sessionStorage.clear()}catch{};document.body.classList.remove('admin-mode');location.replace('/')}catch(e){alert(e.message)}}
function inquiry(id,title){modal(`<h3>استفسار عن ${title}</h3><div class="field"><label>الاسم</label><input id="inName" class="input"></div><div class="field"><label>الجوال</label><input id="inPhone" class="input"></div><div class="field"><label>الرسالة</label><textarea id="inMsg" class="input"></textarea></div><button class="btn primary" onclick="sendInquiry('${id}')">إرسال</button>`)}
async function sendInquiry(id){await api('/api/inquiries',{method:'POST',body:JSON.stringify({assetId:id,name:$('#inName').value,phone:$('#inPhone').value,message:$('#inMsg').value})});closeModal();alert('تم إرسال الاستفسار')}
function reserve(id){modal(`<h3>طلب حجز</h3><p class="muted">سيتم تثبيت الحجز بعد الاتفاق وتسجيل العربون من الإدارة.</p><div class="two"><div class="field"><label>الاسم</label><input id="rn" class="input"></div><div class="field"><label>الجوال</label><input id="rp" class="input"></div></div><div class="two"><div class="field"><label>من</label><input id="rf" class="input" type="datetime-local"></div><div class="field"><label>إلى</label><input id="rt" class="input" type="datetime-local"></div></div><button class="btn primary" onclick="sendReserve('${id}')">إرسال طلب الحجز</button>`)}
async function sendReserve(id){const from=$('#rf').value;const to=$('#rt').value;await api('/api/reservations',{method:'POST',body:JSON.stringify({assetId:id,name:$('#rn').value,phone:$('#rp').value,fromAt:from?new Date(from).toISOString():null,toAt:to?new Date(to).toISOString():null})});closeModal();alert('تم إرسال طلب الحجز، وسيتم تثبيته بعد الاتفاق وتسجيل العربون')}
function offer(id){modal(`<h3>تقديم عرض شراء</h3><div class="field"><label>الاسم</label><input id="on" class="input"></div><div class="field"><label>الجوال</label><input id="op" class="input"></div><div class="field"><label>قيمة العرض</label><input id="oa" class="input" type="number"></div><div class="field"><label>ملاحظة</label><textarea id="om" class="input"></textarea></div><button id="offerFormBtn" class="btn primary" onclick="sendOffer('${id}')">إرسال</button>`)}
async function sendOffer(id){if(window.__offerBusy)return;const btn=document.querySelector('#offerFormBtn');window.__offerBusy=true;if(btn){btn.disabled=true;btn.textContent='جارٍ إرسال العرض...'}try{const clientRequestId=window.__offerRequestId||(window.__offerRequestId=crypto.randomUUID());await api('/api/offers',{method:'POST',body:JSON.stringify({assetId:id,name:$('#on').value,phone:$('#op').value,amount:$('#oa').value,note:$('#om').value,clientRequestId})});window.__offerRequestId=null;closeModal();alert('تم إرسال العرض')}catch(e){window.__offerBusy=false;if(btn){btn.disabled=false;btn.textContent='إرسال العرض'}alert(e.message)}}
async function dashboard(tab='overview',fromHistory=false){state.tab=tab;let d;try{d=await api('/api/admin/dashboard')}catch(e){if(navigator.onLine)throw e;d={system:state.settings||{name:'حوشك'},counts:{assets:0,storage:0,sale:0,rent:0,reservations:0,inquiries:0,offers:0},finance:{income:0,expense:0,net:0}}}const nav=[['overview','الرئيسية'],['assets','الأصول'],['storage','التخزين'],['reservations','الحجوزات'],['offers','العروض'],['orders','الطلبات'],['finance','المالية'],['invoices','الفواتير'],['contracts','العقود'],['locations','مواقع الحوش'],['conditions','محاضر الاستلام والتسليم'],['users','المستخدمون'],['owners','الملاك'],['categories','التصنيفات'],['vehicleTypes','أنواع المركبات'],['inquiries','الاستفسارات'],['reports','التقارير'],['settings','إعدادات النظام'],['audit','سجل التدقيق']];document.querySelector('#app').innerHTML=adminShell(`<main class="container"><div class="panel"><h2>لوحة الإدارة — ${esc(d.system.name)}</h2><div class="tabs">${nav.map(x=>`<button class="btn ${tab===x[0]?'active':''}" onclick="dashboard('${x[0]}')">${x[1]}</button>`).join('')}</div></div><div id="dashContent">${tab==='overview'?overview(d):''}</div></main>`);if(tab!=='overview')await loadTab(tab);if(!fromHistory)navigate({view:'dashboard',tab},`#dashboard-${tab}`)}
function overview(d){return `<div class="stats"><div class="stat">الأصول الحالية<strong>${d.counts.assets}</strong></div><div class="stat">توقيف<strong>${d.counts.storage}</strong></div><div class="stat">بيع<strong>${d.counts.sale}</strong></div><div class="stat">إيجار<strong>${d.counts.rent}</strong></div><div class="stat">حجوزات معلقة<strong>${d.counts.reservations}</strong></div><div class="stat">استفسارات<strong>${d.counts.inquiries}</strong></div><div class="stat">عروض<strong>${d.counts.offers}</strong></div></div><div class="panel"><h3>المالية</h3><div class="stats"><div class="stat">الدخل<strong>${money(d.finance.income)}</strong></div><div class="stat">المصروف<strong>${money(d.finance.expense)}</strong></div><div class="stat">الصافي<strong>${money(d.finance.net)}</strong></div></div></div>`}
async function loadTab(tab){const el=$('#dashContent');if(tab==='assets'){let xs=[];try{xs=await api('/api/admin/assets')}catch(e){if(navigator.onLine)throw e}const pending=offlineQueue().filter(x=>x.type==='ASSET_CREATE');el.innerHTML=`<div class="panel"><div class="toolbar"><button class="btn primary btn-add-asset" onclick="assetForm()">＋ إضافة أصل جديد</button><input id="aq" class="input" placeholder="بحث: اسم المالك أو AST أو REC أو الموقع..." oninput="filterAssets(this.value)"></div>${pending.length?`<div class="notice">🟠 يوجد ${pending.length} أصل محفوظ على الجهاز بانتظار عودة الإنترنت والمزامنة التلقائية.</div>`:''}<div class="tablewrap"><table><thead><tr><th>المالك وبيانات الهوية</th><th>نوع المركبة / المعدة</th><th>الموديل</th><th>الكود</th><th>الغرض</th><th>الحالة</th><th>الموقع</th><th>أضافه</th><th>الإظهار</th><th></th></tr></thead><tbody id="assetRows">${assetRows(xs)}</tbody></table></div></div>`}
else if(tab==='storage'){const xs=await api('/api/admin/storage');el.innerHTML=`<div class="panel"><h3>التخزين</h3><div class="tablewrap"><table><tr><th>الأصل</th><th>الأيام</th><th>المستحق</th><th>المدفوع</th><th>المتبقي</th><th></th></tr>${xs.map(x=>`<tr><td>${esc(x.asset?.title)}</td><td>${x.accrued.days}</td><td>${money(x.accrued.current)}</td><td>${money(x.accrued.charge?.paid||0)}</td><td>${money(Math.max(0,(x.accrued.current||x.total||0)-(x.accrued.charge?.paid||0)))}</td><td>${x.accrued.charge?`<button class="btn" onclick="storagePay('${x.id}')">دفعة</button>`:''}</td></tr>`).join('')}</table></div></div>`}
else if(tab==='reservations'){const xs=await api('/api/admin/reservations');el.innerHTML=`<div class="panel"><h3>الحجوزات</h3><table><tr><th>رقم الحجز</th><th>الأصل</th><th>العميل</th><th>من</th><th>إلى</th><th>الحالة</th><th></th></tr>${xs.map(r=>`<tr><td>${esc(r.code||r.id)}</td><td>${esc(r.asset?.title)}</td><td>${esc(r.customer?.name)}<br>${esc(r.customer?.phone)}</td><td>${esc(dateText(r.fromAt))}</td><td>${esc(r.toAt?dateText(r.toAt):'مفتوح')}</td><td>${statusArabic(r.status)}${r.depositAmount?`<br><small>العربون: ${money(r.depositAmount)}</small>`:''}</td><td>${r.status==='PENDING'?`<button class="btn" onclick="reservationStatus('${r.id}','CONFIRMED')">تأكيد بعربون</button> <button class="btn danger" onclick="reservationStatus('${r.id}','REJECTED')">رفض</button>`:r.status==='CONFIRMED'?`<button class="btn" onclick="reservationStatus('${r.id}','COMPLETED')">إتمام العملية</button> <button class="btn danger" onclick="reservationStatus('${r.id}','CANCELLED')">إلغاء الحجز</button>`:''}</td></tr>`).join('')}</table></div>`}
else if(tab==='offers'){const xs=await api('/api/admin/offers');el.innerHTML=`<div class="panel"><h3>عروض الشراء</h3><table><tr><th>رقم العرض</th><th>الأصل</th><th>العميل</th><th>العرض</th><th>الحالة</th><th></th></tr>${xs.map(o=>`<tr><td>${esc(o.code||o.id)}</td><td>${esc(o.asset?.title)}</td><td>${esc(o.name)}<br>${esc(o.phone)}</td><td>${money(o.amount)}</td><td>${statusArabic(o.status)}</td><td><button class="btn" onclick="offerStatus('${o.id}','ACCEPTED')">قبول</button> <button class="btn danger" onclick="offerStatus('${o.id}','REJECTED')">رفض</button></td></tr>`).join('')}</table></div>`}
else if(tab==='orders'){const xs=await api('/api/admin/orders');el.innerHTML=`<div class="panel"><div class="toolbar"><button class="btn primary" onclick="orderForm()">＋ تسجيل طلب جديد</button></div><table><tr><th>رقم الطلب</th><th>العميل</th><th>نوع الطلب</th><th>الطلب</th><th>الأصل</th><th>المبلغ</th><th>الحالة</th><th></th></tr>${xs.map(o=>`<tr><td>${esc(o.id)}</td><td>${esc(o.customerName)}<br>${esc(o.phone)}</td><td>${esc(o.type)}</td><td>${esc(o.description)}</td><td>${esc(o.asset?.title||'-')}</td><td>${o.amount?money(o.amount):'-'}</td><td>${esc(o.status)}</td><td>${o.status==='NEW'?`<button class="btn" onclick="orderStatus('${o.id}','IN_PROGRESS')">بدء</button>`:''}${o.status==='IN_PROGRESS'?`<button class="btn success" onclick="orderStatus('${o.id}','COMPLETED')">إتمام</button>`:''}</td></tr>`).join('')}</table></div>`}
else if(tab==='finance'){const xs=await api('/api/admin/transactions');el.innerHTML=`<div class="panel"><button class="btn primary" onclick="financeForm()">إضافة حركة مالية</button><table><tr><th>النوع</th><th>التصنيف</th><th>المبلغ</th><th>الوصف</th><th>التاريخ</th></tr>${xs.map(x=>`<tr><td>${x.type==='INCOME'?'دخل':'مصروف'}</td><td>${esc(x.category||'أخرى')}</td><td>${money(x.amount)}</td><td>${esc(x.description)}</td><td>${esc(dateText(x.createdAt))}</td></tr>`).join('')}</table></div>`}
else if(tab==='invoices'){const xs=await api('/api/admin/invoices');el.innerHTML=`<div class="panel"><button class="btn primary" onclick="invoiceForm()">إصدار فاتورة</button><table><tr><th>رقم</th><th>الطرف</th><th>الإجمالي</th><th>المدفوع</th><th>المتبقي</th><th>الحالة</th></tr>${xs.map(x=>`<tr><td>${x.number}</td><td>${esc(x.partyName)}</td><td>${money(x.total)}</td><td>${money(x.paid)}</td><td>${money(x.balance)}</td><td>${statusArabic(x.status)}</td></tr>`).join('')}</table></div>`}
else if(tab==='contracts'){const xs=await api('/api/admin/contracts');el.innerHTML=`<div class="panel"><button class="btn primary" onclick="contractForm()">إنشاء عقد وساطة</button><table><tr><th>رقم العقد</th><th>الأصل</th><th>الطرف</th><th>القيمة</th><th>العمولة</th><th>الحالة</th></tr>${xs.map(x=>`<tr><td>${esc(x.code||x.id)}</td><td>${esc(x.asset?.title)}</td><td>${esc(x.partyName)}</td><td>${money(x.amount)}</td><td>${money(x.commissionValue)}</td><td>${statusArabic(x.status)}</td></tr>`).join('')}</table></div>`}
else if(tab==='locations'){const xs=await api('/api/admin/locations');el.innerHTML=`<div class="panel"><button class="btn primary" onclick="locationForm()">إضافة موقع</button><table><tr><th>الرمز</th><th>الاسم</th><th>المنطقة</th><th>عدد الأصول</th></tr>${xs.map(x=>`<tr><td>${x.code}</td><td>${esc(x.name)}</td><td>${esc(x.zone)}</td><td>${x.assetCount}</td></tr>`).join('')}</table></div>`}
else if(tab==='conditions'){const xs=await api('/api/admin/conditions');el.innerHTML=`<div class="panel"><h3>محاضر الاستلام والتسليم</h3><p class="muted">المحضر يوثق حالة الأصل عند دخوله أو خروجه من الحوش، مثل الحالة الظاهرية والعداد وساعات التشغيل والملحقات والملاحظات، مع تسجيل الموظف والتاريخ.</p><button class="btn primary" onclick="conditionForm()">إضافة محضر استلام/تسليم</button><div class="tablewrap"><table><tr><th>الأصل</th><th>النوع</th><th>الحالة</th><th>العداد</th><th>الساعات</th><th>المسؤول</th><th>الملاحظات</th></tr>${xs.map(x=>`<tr><td>${esc(x.asset?.title)}</td><td>${x.type==='ENTRY'?'استلام / دخول':'تسليم / خروج'}</td><td>${esc(x.condition)}</td><td>${esc(x.odometer||'-')}</td><td>${esc(x.engineHours||'-')}</td><td>${esc(x.user?.name||'-')}</td><td>${esc(x.notes||'-')}</td></tr>`).join('')}</table></div></div>`}
else if(tab==='owners'){const xs=await api('/api/admin/owners?q=');el.innerHTML=`<div class="panel"><div class="section-head"><div><h3>الملاك</h3><p class="muted">كل مالك يُسجل مرة واحدة ويمكن ربط عدة مركبات ومعدات به.</p></div><button class="btn primary" onclick="ownerForm()">إضافة مالك</button></div><table><tr><th>المالك</th><th>الجوال</th><th>نوع الهوية</th><th>رقم الهوية</th><th>الأصول</th><th></th></tr>${xs.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.phone)}</td><td>${identityName(x.identityType)}</td><td>${esc(x.identityNumber)}</td><td>${x.assetCount||0}</td><td><button class="btn" onclick='ownerForm(${JSON.stringify(x)})'>تعديل</button></td></tr>`).join('')}</table></div>`}
else if(tab==='users'){const xs=await api('/api/admin/users');el.innerHTML=`<div class="panel"><button class="btn primary" onclick="userForm()">إضافة مستخدم/مالك</button><table><tr><th>الاسم</th><th>الجوال</th><th>نوع الهوية</th><th>رقم الهوية</th><th>الدور</th><th>نشط</th></tr>${xs.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.phone)}</td><td>${identityName(x.identityType)}</td><td>${esc(x.identityNumber)}</td><td>${({CUSTOMER:'عميل',RECEPTION:'استقبال',SALES:'مبيعات',YARD:'حوش',ACCOUNTING:'محاسبة',MANAGER:'مدير',ADMIN:'مدير النظام'})[x.role]||x.role}</td><td>${x.active?'نعم':'لا'}</td></tr>`).join('')}</table></div>`}
else if(tab==='vehicleTypes'){const xs=await api('/api/admin/vehicle-types');el.innerHTML=`<div class="panel"><div class="section-head"><div><h3>إدارة أنواع المركبات</h3><p class="muted">أضف أو عدّل أو عطّل الأنواع التي تظهر عند تسجيل المركبات.</p></div><button class="btn primary" onclick="vehicleTypeForm()">إضافة نوع مركبة</button></div><table><tr><th>النوع</th><th>الحالة</th><th></th></tr>${xs.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.active?'نشط':'معطل'}</td><td><button class="btn" onclick='vehicleTypeForm(${JSON.stringify(x)})'>تعديل</button> <button class="btn danger" onclick="deleteVehicleType('${x.id}')">حذف/تعطيل</button></td></tr>`).join('')}</table></div>`}
else if(tab==='categories'){const xs=await api('/api/admin/categories');el.innerHTML=`<div class="panel"><button class="btn primary" onclick="categoryForm()">إضافة تصنيف</button><table><tr><th>الاسم</th><th>بيع</th><th>إيجار</th><th>توقيف</th><th>نشط</th><th></th></tr>${xs.map(x=>`<tr><td>${x.icon||'📦'} ${esc(x.name)}</td><td>${x.allowSale?'نعم':'لا'}</td><td>${x.allowRent?'نعم':'لا'}</td><td>${x.allowStorage?'نعم':'لا'}</td><td>${x.active?'نعم':'لا'}</td><td><button class="btn" onclick="editCategory('${x.id}')">تعديل</button></td></tr>`).join('')}</table></div>`}
else if(tab==='inquiries'){const xs=await api('/api/admin/inquiries');el.innerHTML=`<div class="panel"><table><tr><th>الأصل</th><th>العميل</th><th>الرسالة</th><th>الحالة</th><th></th></tr>${xs.map(x=>`<tr><td>${esc(x.asset?.title)}</td><td>${esc(x.name)}<br>${esc(x.phone)}</td><td>${esc(x.message)}</td><td>${statusArabic(x.status)}</td><td><button class="btn" onclick="reply('${x.id}')">رد</button></td></tr>`).join('')}</table></div>`}
else if(tab==='reports'){el.innerHTML=`<div class="panel"><div class="toolbar"><button class="btn" onclick="report(30)">30 يومًا</button><button class="btn" onclick="report(90)">90 يومًا</button><button class="btn" onclick="report(365)">سنة</button></div><div id="report"></div></div>`;report(30)}
else if(tab==='settings'){const s=await api('/api/admin/settings'),cs=await api('/api/currencies');el.innerHTML=`<div class="panel"><h3>هوية النظام والإعدادات</h3><div class="two"><div class="field"><label>اسم النظام</label><input id="sn" class="input" value="${esc(s.name)}"></div><div class="field"><label>الوصف المختصر</label><input id="st" class="input" value="${esc(s.tagline)}"></div><div class="field"><label>الدولة</label><input id="sco" class="input" value="${esc(s.country)}"></div><div class="field"><label>المدينة</label><input id="sci" class="input" value="${esc(s.city)}"></div><div class="field"><label>نوع العملة</label><select id="sc" class="select">${cs.map(c=>`<option value="${c.code}" ${c.code===s.currency?'selected':''}>${c.name} (${c.code})</option>`).join('')}</select></div><div class="field"><label>مفتاح الدولة</label><input id="scc" class="input" value="${esc(s.countryCode||'966')}" placeholder="966"></div><div class="field"><label>واتساب</label><input id="sw" class="input" value="${esc(s.whatsapp)}"></div><div class="field"><label>الهاتف</label><input id="sp" class="input" value="${esc(s.phone)}"></div><div class="field"><label>البريد</label><input id="se" class="input" value="${esc(s.email)}"></div><div class="field"><label>العنوان</label><input id="sa" class="input" value="${esc(s.address)}"></div><div class="field"><label>خط العرض (Latitude)</label><input id="sla" class="input" value="${esc(s.latitude||'')}" placeholder="مثال: 24.xxxxxx"></div><div class="field"><label>خط الطول (Longitude)</label><input id="slo" class="input" value="${esc(s.longitude||'')}" placeholder="مثال: 46.xxxxxx"></div><div class="field"><label>رابط الخريطة المباشر</label><input id="smu" class="input" value="${esc(s.mapsUrl||'')}" placeholder="يمكنك لصق رابط Google Maps"></div><div class="field"><label>معاينة الموقع</label><div class="toolbar"><a class="btn" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.latitude&&s.longitude?`${s.latitude},${s.longitude}`:(s.address||'الرياض حي السلي مقابل مصنع الألبان'))}">📍 فتح الخريطة</a><span class="muted">احفظ الإحداثيات أو رابط الخريطة ليتم استخدامه في زر الوصول للعميل.</span></div></div><div class="field"><label>سعر التخزين الافتراضي</label><input id="sr" class="input" type="number" value="${s.storageDefaultRate}"></div></div><hr><h3>محتوى واجهة العميل</h3><p class="muted">هذه النصوص تظهر في صفحة «عن حوشك» والشريط التعريفي أسفل شريط التنقل.</p><div class="two"><div class="field"><label>مالك الحوش</label><input id="son" class="input" value="${esc(s.ownerName||'أبو مناحي السبيعي')}"></div><div class="field"><label>رقم مالك الحوش</label><input id="sop" class="input" value="${esc(s.ownerPhone||'00966554795400')}" placeholder="مثال: 00966..."></div><div class="field"><label>مدير الحوش</label><input id="smn" class="input" value="${esc(s.managerName||'أبو أنس الإدريسي')}"></div><div class="field"><label>رقم مدير الحوش</label><input id="smp" class="input" value="${esc(s.managerPhone||'00966507882962')}" placeholder="مثال: 00966..."></div><div class="field"><label>تطوير وبرمجة</label><input id="sdn" class="input" value="${esc(s.developerName||'هيثم القاضي')}"></div></div><div class="field"><label>عنوان «عن حوشك»</label><input id="sat" class="input" value="${esc(s.aboutTitle||'عن حوشك')}"></div><div class="field"><label>نبذة عن حوشك</label><textarea id="sab" class="input">${esc(s.aboutText||'')}</textarea></div><div class="field"><label>الخدمات التي نقدمها</label><textarea id="ssv" class="input">${esc(s.servicesText||'')}</textarea></div><div class="field"><label>طريقة الاستخدام</label><textarea id="shu" class="input">${esc(s.howToText||'')}</textarea></div><div class="field"><label>التطوير المستقبلي</label><textarea id="sfu" class="input">${esc(s.futureText||'')}</textarea></div><div class="field"><label>رسائل الشريط التعريفي — رسالة في كل سطر</label><textarea id="stm" class="input" rows="5">${esc((s.tickerMessages||[]).join('\n'))}</textarea></div><button class="btn primary" onclick="saveSettings()">حفظ الإعدادات</button></div>`}
else if(tab==='audit'){const xs=await api('/api/admin/audit');el.innerHTML=`<div class="panel"><h3>سجل التدقيق</h3><p class="muted">سجل يوضح من قام بالعملية وماذا تم تغييره ومتى، بصياغة مفهومة للإدارة.</p><div class="tablewrap"><table><tr><th>المسؤول</th><th>العملية</th><th>الكيان</th><th>التفاصيل</th><th>التاريخ</th></tr>${xs.map(x=>`<tr><td>${esc(x.actorName||x.actor?.name||'النظام')}</td><td>${actionName(x.action)}</td><td>${entityName(x.entity)}</td><td><div class="audit-details">${auditDetails(x.details)||'لا توجد تفاصيل إضافية'}</div></td><td>${esc(dateText(x.createdAt))}</td></tr>`).join('')}</table></div></div>`}stabilizeAdminTables();}
function assetRows(xs){return xs.map(a=>`<tr><td><strong>${esc(a.owner?.name||'الحوش / الإدارة')}</strong><br><small>${a.owner?`${identityName(a.owner.identityType)} · ${esc(a.owner.identityNumber||'')}<br>الهاتف: ${esc(a.owner.phone||'')}`:'-'}</small></td><td>${esc(a.customFields?.vehicleType==='OTHER'?a.customFields?.vehicleTypeOther:(a.customFields?.vehicleTypeName||a.customFields?.vehicleType||a.customFields?.assetType||a.customFields?.equipmentType||a.customFields?.truckType||a.customFields?.headType||a.category?.name||'-'))}</td><td>${esc(a.model||'-')}</td><td>${esc(a.code||'-')}</td><td>${purposeName(a.purpose)}</td><td>${statusName(a.status)}</td><td>${esc(a.locationCode||'-')}</td><td>${esc(a.createdBy?.name||'-')}</td><td>${a.publicVisible?'نعم':'لا'}</td><td><button class="btn" onclick="assetRecord('${a.id}')">السجل</button> <button class="btn" onclick="showAssetQR('${a.id}')">▣ QR</button> <button class="btn" onclick="editAsset('${a.id}')">تعديل</button>${a.status!=='EXITED'?` <button class="btn danger" onclick="exitAsset('${a.id}')">خروج</button>`:''}</td></tr>`).join('')}

async function showAssetQR(id){try{const a=await api('/api/admin/assets/'+id);if(!a.publicToken)throw Error('رمز الباركود غير متوفر لهذا الأصل');const url=location.origin+'/asset/'+encodeURIComponent(a.publicToken);modal(`<div class="qr-panel"><h3>باركود الأصل</h3><p><strong>${esc(a.title)}</strong><br>كود الأصل: <strong>${esc(a.code)}</strong><br>رابط السجل العام: لا يعرض بيانات المالك أو رقمه.</p><div id="assetQrBox" style="display:flex;justify-content:center;margin:18px 0"></div><div class="toolbar"><button class="btn primary" onclick="printAssetQR('${a.id}')">🖨️ طباعة بطاقة الباركود</button><button class="btn" onclick="navigator.clipboard?.writeText(${JSON.stringify(url)});alert('تم نسخ رابط الباركود')">نسخ الرابط</button></div></div>`);if(typeof QRCode==='undefined')throw Error('تعذر تحميل مولد QR');new QRCode(document.getElementById('assetQrBox'),{text:url,width:220,height:220,correctLevel:QRCode.CorrectLevel.M});window.__assetQR={a,url}}catch(e){alert(e.message)}}
async function printAssetQR(id){try{const a=await api('/api/admin/assets/'+id);if(!a.publicToken)throw Error('رمز الباركود غير متوفر');const url=location.origin+'/asset/'+encodeURIComponent(a.publicToken);const w=window.open('','_blank');if(!w)throw Error('اسمح بالنوافذ المنبثقة للطباعة');w.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>بطاقة ${esc(a.code)}</title><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"><\/script><style>body{font-family:Arial,sans-serif;text-align:center;padding:30px}.card{width:340px;margin:auto;border:1px solid #ddd;border-radius:18px;padding:24px}h2{margin:0 0 8px}#q{display:flex;justify-content:center;margin:20px}</style></head><body><div class="card"><h2>حوشك</h2><strong>${esc(a.title)}</strong><div>كود الأصل: ${esc(a.code)}</div><div id="q"></div><p>امسح الباركود لمعرفة تفاصيل الأصل والتواصل مع إدارة الحوش.</p></div><script>new QRCode(document.getElementById('q'),{text:${JSON.stringify(url)},width:220,height:220});setTimeout(()=>window.print(),500);<\/script></body></html>`);w.document.close()}catch(e){alert(e.message)}}
async function assetRecord(id){try{const a=await api('/api/admin/assets/'+id);modal(`<h3>سجل الأصل — ${esc(a.title)}</h3><div class="toolbar"><button class="btn primary" onclick="entryReceipt('${a.id}')">📄 سند استلام الأصل</button><button class="btn success" onclick="paymentReceiptForm('${a.id}')">💰 سند استلام مبلغ</button><button class="btn" onclick="showAssetQR('${a.id}')">▣ باركود / QR</button></div><div class="stats"><div class="stat">المالك<strong>${esc(a.owner?.name||'الحوش / الإدارة')}</strong><small>${esc(a.owner?.phone||'')}</small></div><div class="stat">أضافه<strong>${esc(a.createdBy?.name||'-')}</strong></div><div class="stat">آخر تعديل<strong>${esc(a.lastUpdatedBy?.name||'-')}</strong></div><div class="stat">التسليم / الخروج<strong>${esc(a.exitBy?.name||'-')}</strong></div></div><div class="field-section"><h4>سجل الإجراءات</h4>${(a.history||[]).map(h=>`<div class="audit-item"><strong>${esc(h.note||'إجراء')}</strong><span>${esc(h.changedBy?.name||'النظام')} — ${esc(dateText(h.createdAt))}</span></div>`).join('')||'<div class="muted">لا توجد إجراءات إضافية.</div>'}</div><div class="field-section"><h4>محاضر الاستلام والتسليم</h4>${(a.conditions||[]).map(c=>`<div class="audit-item"><strong>${c.type==='ENTRY'?'استلام / دخول':'تسليم / خروج'}</strong><span>${esc(c.user?.name||'النظام')} — ${esc(dateText(c.createdAt))}</span><small>${esc(c.condition||'')} ${esc(c.notes||'')}</small></div>`).join('')||'<div class="muted">لا توجد محاضر.</div>'}</div>`)}catch(e){alert(e.message)}}
function stabilizeAdminTables(){const root=$('#dashContent');if(!root)return;root.querySelectorAll('table').forEach(t=>{if(t.parentElement?.classList.contains('tablewrap'))return;const w=document.createElement('div');w.className='tablewrap';t.parentNode.insertBefore(w,t);w.appendChild(t)});}

function filterAssets(q){api('/api/admin/assets?q='+encodeURIComponent(q)).then(xs=>$('#assetRows').innerHTML=assetRows(xs))}
async function assetForm(a={}){window.__assetEdit=a;window.__returnToAsset=false;window.__assetSaveBusy=false;window.__assetRequestId=a.id?null:crypto.randomUUID();const owners=await api('/api/admin/owners?q=');state.owners=owners;saveSnapshot();const vtypes=await api('/api/vehicle-types');const selectedCat=state.cats.find(c=>c.id===a.categoryId)||state.cats[0]||{};const purpose=a.purpose||'SALE';const ownerIsYard=a.ownerType==='USER'||(a.ownerId&&state.me&&a.ownerId===state.me.id);const cf=a.customFields||{};const selectedOwner=owners.find(x=>x.id===a.ownerId);const entryLocal=a.entryAt?toLocalInputValue(a.entryAt):toLocalInputValue(new Date().toISOString());modal(`<h3>${a.id?'تعديل أصل':'إضافة أصل جديد'}</h3><div class="purpose-grid"><button type="button" class="purpose-card ${purpose==='SALE'?'selected':''}" data-purpose="SALE" onclick="selectAssetPurpose('SALE')"><span>💰</span><strong>للبيع</strong><small>عرض الأصل للبيع</small></button><button type="button" class="purpose-card ${purpose==='RENT'?'selected':''}" data-purpose="RENT" onclick="selectAssetPurpose('RENT')"><span>🔑</span><strong>للإيجار</strong><small>عرض الأصل للإيجار</small></button><button type="button" class="purpose-card ${purpose==='STORAGE'?'selected':''}" data-purpose="STORAGE" onclick="selectAssetPurpose('STORAGE')"><span>🏠</span><strong>للتوقيف</strong><small>تخزين فقط داخل الحوش</small></button><button type="button" class="purpose-card ${purpose==='SALE_RENT'?'selected':''}" data-purpose="SALE_RENT" onclick="selectAssetPurpose('SALE_RENT')"><span>🔄</span><strong>للبيع والإيجار</strong><small>إتاحة الغرضين</small></button></div><input id="ap" type="hidden" value="${purpose}"><input id="as" type="hidden" value="${a.status||'ACTIVE'}"><div class="field"><label>القسم</label><select id="ag" class="select" onchange="renderDynamicAssetFields();updatePurposeCards();updateAssetPriceFields()">${state.cats.map(c=>`<option value="${c.id}" ${c.id===selectedCat.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field-section owner-section"><h4>بيانات المالك</h4><label class="checkline"><input id="aoy" type="checkbox" ${ownerIsYard?'checked':''} onchange="toggleOwnerChoice()"> المالك هو الحوش / الإدارة</label><div id="ownerPicker" class="owner-picker" style="display:${ownerIsYard?'none':'block'}"><label>اسم المالك</label><input id="aoSearch" class="input" autocomplete="off" placeholder="اكتب اسم المالك للبحث أو لإضافة مالك جديد" value="${esc(selectedOwner?.name||'')}" oninput="$('#ao').value='';searchOwners(this.value)"><input id="ao" type="hidden" value="${esc(selectedOwner?.id||'')}"><div id="ownerSuggestions" class="owner-suggestions"></div><div id="newOwnerFields" class="new-owner-fields" style="display:none"><p class="muted">لا يوجد مالك مطابق. أكمل بيانات المالك الجديد:</p><div class="two"><div class="field"><label>نوع الهوية</label><select id="noi" class="select"><option value="NATIONAL_ID">هوية وطنية</option><option value="PERSONAL_ID">بطاقة شخصية</option><option value="RESIDENCY_ID">هوية مقيم</option><option value="PASSPORT">جواز سفر</option><option value="OTHER">هوية أخرى</option></select></div><div class="field"><label>رقم الهوية</label><input id="non" class="input"></div></div><div class="field"><label>رقم الهاتف</label><input id="nop" class="input"></div></div><div id="selectedOwnerInfo" class="selected-owner"></div></div></div><div class="field-section"><h4>بيانات الدخول</h4><div class="field"><label>تاريخ ووقت الدخول</label><input id="ae" class="input" type="datetime-local" value="${entryLocal}"><small class="muted">يُسجل تلقائيًا بتاريخ ووقت النظام، ويمكن تعديله عند الحاجة.</small></div></div><div id="dynamicFields"></div><div id="priceFields"></div><div class="two"><div class="field"><label>موقع الحوش / الأصل <span class="muted">(اختياري)</span></label><input id="al" class="input" placeholder="اكتب الوصف أو الرمز" value="${esc(a.locationCode)}"></div><div class="field"><label>كود الأصل</label><input id="ac" class="input" value="${esc(a.code||'')}" readonly placeholder="يُنشأ تلقائيًا"></div></div><div class="field"><label>اسم العرض / العنوان</label><input id="at" class="input" value="${esc(a.title||'')}" readonly placeholder="يُولد تلقائيًا من بيانات الأصل"></div><div class="field"><label>الوصف</label><textarea id="ad" class="input" placeholder="تفاصيل إضافية عن الأصل">${esc(a.description)}</textarea></div><div class="field"><label>ملاحظات الدخول</label><textarea id="an" class="input">${esc(a.entryNotes)}</textarea></div><div class="field"><label>صور الأصل</label><div class="image-upload-actions"><label class="btn primary image-pick"><span>📁 اختيار صور من الهاتف</span><input id="ai" type="file" multiple accept="image/*"></label><label class="btn success image-pick"><span>📷 فتح الكاميرا وتصوير المعدة</span><input id="aiCamera" type="file" accept="image/*" capture="environment"></label></div><div id="imageSelectionInfo" class="muted image-selection-info">يمكن اختيار صور من الجهاز أو فتح الكاميرا مباشرة لتصوير المعدة.</div><small class="muted">يمكن إضافة عدة صور، وتظهر للمستخدم على شكل شبكة.</small></div><button id="assetSaveBtn" class="btn primary btn-save-asset" onclick="saveAsset('${a.id||''}')">${a.id?'حفظ التعديلات':'＋ إضافة الأصل وحفظ'}</button>`);window.__vehicleTypes=vtypes;window.__owners=owners;renderDynamicAssetFields(cf);toggleOwnerChoice();updatePurposeCards();updateAssetPriceFields();renderSelectedOwner(selectedOwner);if(selectedOwner)searchOwners(selectedOwner.name);['ai','aiCamera'].forEach(id=>{const el=$('#'+id);if(el)el.addEventListener('change',updateImageSelectionInfo)});updateImageSelectionInfo()}
function toLocalInputValue(iso){const d=new Date(iso);if(Number.isNaN(d.getTime()))return '';const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`}

function renderSelectedOwner(o){const el=$('#selectedOwnerInfo');if(!el)return;el.innerHTML=o?`<div><strong>${esc(o.name)}</strong> · ${esc(o.phone)}<br><small>${identityName(o.identityType)} · ${esc(o.identityNumber)} · ${o.assetCount||0} أصل مرتبط</small></div>`:''}
async function searchOwners(q){const box=$('#ownerSuggestions'),newBox=$('#newOwnerFields');if(!box)return;const term=String(q||'').trim();if(!term){box.innerHTML='';if(newBox)newBox.style.display='none';if($('#selectedOwnerInfo'))$('#selectedOwnerInfo').innerHTML='';return}const xs=await api('/api/admin/owners?q='+encodeURIComponent(term));window.__owners=xs;box.innerHTML=xs.map(o=>`<button type="button" class="owner-suggestion" onclick='selectOwner(${JSON.stringify(o)})'><strong>${esc(o.name)}</strong><span>${esc(o.phone)} · ${identityName(o.identityType)} · ${o.assetCount||0} أصل</span></button>`).join('');if(newBox)newBox.style.display=xs.length?'none':'block';if($('#selectedOwnerInfo'))$('#selectedOwnerInfo').innerHTML=xs.length?'':'<div class="muted">مالك جديد: أكمل البيانات أدناه ثم احفظ الأصل.</div>'}
function selectOwner(o){$('#ao').value=o.id;$('#aoSearch').value=o.name;$('#ownerSuggestions').innerHTML='';if($('#newOwnerFields'))$('#newOwnerFields').style.display='none';renderSelectedOwner(o)}

function ownerForm(o={}){if(!o.id&&window.__assetEdit&&document.querySelector('#ownerPicker'))window.__returnToAsset=true;modal(`<h3>${o.id?'تعديل بيانات المالك':'إضافة مالك جديد'}</h3><div class="field"><label>اسم المالك</label><input id="oname" class="input" value="${esc(o.name||'')}"></div><div class="two"><div class="field"><label>نوع الهوية</label><select id="oit" class="select"><option value="NATIONAL_ID" ${o.identityType==='NATIONAL_ID'?'selected':''}>هوية وطنية</option><option value="PERSONAL_ID" ${o.identityType==='PERSONAL_ID'?'selected':''}>بطاقة شخصية</option><option value="RESIDENCY_ID" ${o.identityType==='RESIDENCY_ID'?'selected':''}>هوية مقيم</option><option value="PASSPORT" ${o.identityType==='PASSPORT'?'selected':''}>جواز سفر</option><option value="OTHER" ${o.identityType==='OTHER'?'selected':''}>هوية أخرى</option></select></div><div class="field"><label>رقم الهوية</label><input id="oin" class="input" value="${esc(o.identityNumber||'')}"></div></div><div class="field"><label>رقم الهاتف</label><input id="oph" class="input" value="${esc(o.phone||'')}"></div><div class="two"><input id="oem" class="input" placeholder="البريد الإلكتروني (اختياري)" value="${esc(o.email||'')}"><input id="oad" class="input" placeholder="العنوان (اختياري)" value="${esc(o.address||'')}"></div><button class="btn primary" onclick="saveOwner('${o.id||''}')">حفظ المالك</button>`)}
async function saveOwner(id){try{const o=await api(id?'/api/admin/owners/'+id:'/api/admin/owners',{method:id?'PUT':'POST',body:JSON.stringify({name:$('#oname').value,identityType:$('#oit').value,identityNumber:$('#oin').value,phone:$('#oph').value,email:$('#oem').value,address:$('#oad').value})});closeModal();if(window.__returnToAsset){window.__returnToAsset=false;assetForm({...window.__assetEdit,ownerId:o.id,ownerType:'OWNER'})}else dashboard('owners')}catch(e){alert(e.message)}}
function updatePurposeCards(){const c=state.cats.find(x=>x.id===$('#ag')?.value);if(!c)return;const allowed={SALE:!!c.allowSale,RENT:!!c.allowRent,STORAGE:!!c.allowStorage,SALE_RENT:!!c.allowSale&&!!c.allowRent};document.querySelectorAll('.purpose-card').forEach(x=>{const ok=allowed[x.dataset.purpose];x.disabled=!ok;x.classList.toggle('disabled',!ok);});const current=$('#ap')?.value;if(current&&!allowed[current]){const next=['SALE','RENT','STORAGE','SALE_RENT'].find(x=>allowed[x]);if(next)selectAssetPurpose(next);}}
function selectAssetPurpose(p){$('#ap').value=p;document.querySelectorAll('.purpose-card').forEach(x=>x.classList.toggle('selected',x.dataset.purpose===p));updateAssetPriceFields();}
function toggleOwnerChoice(){const c=$('#aoy'),p=$('#ownerPicker');if(!c||!p)return;p.style.display=c.checked?'none':'block';if(c.checked){$('#ao').value='';if($('#aoSearch'))$('#aoSearch').value='';if($('#selectedOwnerInfo'))$('#selectedOwnerInfo').innerHTML='';}}
function renderDynamicAssetFields(values={}){const c=state.cats.find(x=>x.id===$('#ag')?.value)||{};let fields=Array.isArray(c.fields)&&c.fields.length?c.fields:[{key:'assetType',label:'نوع الأصل / المعدة',type:'text'},{key:'model',label:'الموديل',type:'text'}];fields=fields.filter(f=>f.key!=='year');if(c.slug==='vehicles'){fields=[{key:'vehicleType',label:'الشركة / النوع',type:'select',options:(window.__vehicleTypes||[]).map(v=>({value:v.id,label:v.name})).concat([{value:'OTHER',label:'أخرى'}])},{key:'model',label:'الموديل',type:'text'},{key:'color',label:'اللون',type:'text'},{key:'plateNumber',label:'رقم اللوحة',type:'text'},{key:'variant',label:'الفئة (اختياري)',type:'text'}];$('#dynamicFields').innerHTML=`<div class="field-section"><h4>بيانات ${esc(c.name||'الأصل')}</h4><div class="two">${fields.map(f=>{const v=values[f.key]??'';if(f.type==='select')return `<div class="field"><label>${esc(f.label)}</label><select class="select dynamic-field" data-key="${esc(f.key)}" onchange="updateGeneratedTitle();toggleVehicleOther()"><option value="">اختر</option>${(f.options||[]).map(o=>{const val=typeof o==='string'?o:o.value,lab=typeof o==='string'?o:o.label;return `<option value="${esc(val)}" ${String(v)===String(val)?'selected':''}>${esc(lab)}</option>`}).join('')}</select>${f.key==='vehicleType'?`<input id="vehicleTypeOther" class="input" placeholder="اكتب نوع المركبة" value="${esc(values.vehicleTypeOther||'')}" style="display:${v==='OTHER'?'block':'none'};margin-top:6px" oninput="updateGeneratedTitle()">`:''}</div>`;return `<div class="field"><label>${esc(f.label)}</label><input class="input dynamic-field" data-key="${esc(f.key)}" type="text" value="${esc(v)}" oninput="updateGeneratedTitle()"></div>`}).join('')}</div></div>`;updateGeneratedTitle();}else{$('#dynamicFields').innerHTML=`<div class="field-section"><h4>بيانات ${esc(c.name||'الأصل')}</h4><div class="two">${fields.map(f=>`<div class="field"><label>${esc(f.label)}</label><input class="input dynamic-field" data-key="${esc(f.key)}" type="text" value="${esc(values[f.key]??'')}" oninput="updateGeneratedTitle()"></div>`).join('')}</div></div>`;updateGeneratedTitle();}}

function toggleVehicleOther(){const x=$('.dynamic-field[data-key="vehicleType"]'),o=$('#vehicleTypeOther');if(o)o.style.display=x?.value==='OTHER'?'block':'none';}
function updateGeneratedTitle(){const c=state.cats.find(x=>x.id===$('#ag')?.value);if(!c)return;const cf={};document.querySelectorAll('.dynamic-field').forEach(x=>cf[x.dataset.key]=x.value);if($('#vehicleTypeOther'))cf.vehicleTypeOther=$('#vehicleTypeOther').value;const parts=c.slug==='vehicles'?[cf.vehicleType==='OTHER'?cf.vehicleTypeOther:(window.__vehicleTypes||[]).find(v=>v.id===cf.vehicleType)?.name,cf.model]:[cf.assetType,cf.equipmentType,cf.boxType,cf.model];if($('#at'))$('#at').value=parts.filter(x=>String(x||'').trim()).join(' ').trim()||c.name||'أصل جديد';}

function updateAssetPriceFields(){const p=$('#ap')?.value||'SALE',a=window.__assetEdit||{};let h='';if(p==='SALE')h=`<div class="two"><div class="field"><label>سعر البيع المطلوب</label><input id="asp" class="input" type="number" min="0" value="${esc(a.salePrice??'')}"></div><div class="field"><label>السوم الحالي <span class="muted">(اختياري)</span></label><input id="acb" class="input" type="number" min="0" value="${esc(a.currentBid??'')}" placeholder="اتركه فارغًا إذا لم يوجد سوم"></div></div>`;if(p==='RENT')h=`<div class="two"><div class="field"><label>سعر الإيجار</label><input id="arp" class="input" type="number" value="${esc(a.rentPrice??'')}"></div><div class="field"><label>وحدة الإيجار</label><select id="aru" class="select"><option value="يوم">يومي</option><option value="أسبوع">أسبوعي</option><option value="شهر">شهري</option></select></div></div><div class="field"><label>رسوم توقيف الحوش اليومية</label><input id="adf" class="input" type="number" value="${esc(a.dailyStorageFee??state.settings.storageDefaultRate)}"></div>`;if(p==='SALE_RENT')h=`<div class="two"><div class="field"><label>سعر البيع المطلوب</label><input id="asp" class="input" type="number" min="0" value="${esc(a.salePrice??'')}"></div><div class="field"><label>السوم الحالي <span class="muted">(اختياري)</span></label><input id="acb" class="input" type="number" min="0" value="${esc(a.currentBid??'')}" placeholder="اتركه فارغًا إذا لم يوجد سوم"></div></div><div class="two"><div class="field"><label>سعر الإيجار</label><input id="arp" class="input" type="number" value="${esc(a.rentPrice??'')}"></div><div class="field"><label>وحدة الإيجار</label><select id="aru" class="select"><option value="يوم">يومي</option><option value="أسبوع">أسبوعي</option><option value="شهر">شهري</option></select></div></div><div class="field"><label>رسوم توقيف الحوش اليومية</label><input id="adf" class="input" type="number" value="${esc(a.dailyStorageFee??state.settings.storageDefaultRate)}"></div>`;if(p==='STORAGE')h=`<div class="field"><label>سعر التوقيف اليومي</label><input id="adf" class="input" type="number" value="${esc(a.dailyStorageFee??state.settings.storageDefaultRate)}"></div>`;$('#priceFields').innerHTML=h;if($('#aru'))$('#aru').value=a.rentUnit||'يوم';}
function updateImageSelectionInfo(){const files=[...($('#ai')?.files||[]),...($('#aiCamera')?.files||[])];const el=$('#imageSelectionInfo');if(el)el.textContent=files.length?`تم اختيار ${files.length} صورة، وسيتم حفظها كلها.`:'يمكن اختيار صور من الجهاز أو فتح الكاميرا مباشرة لتصوير المعدة.';}
async function saveAsset(id){if(window.__assetSaveBusy)return;const btn=$('#assetSaveBtn');window.__assetSaveBusy=true;if(btn){btn.disabled=true;btn.textContent=id?'جارٍ حفظ التعديلات...':'جارٍ إضافة الأصل...';}try{const ownerYard=$('#aoy')?.checked,purpose=$('#ap').value,customFields={};document.querySelectorAll('.dynamic-field').forEach(x=>customFields[x.dataset.key]=x.value);if($('#vehicleTypeOther'))customFields.vehicleTypeOther=$('#vehicleTypeOther').value;let ownerId=$('#ao').value;const ownerType=ownerYard?'USER':'OWNER';const offlineNewAsset=!id&&!navigator.onLine;let offlineOwner=null;if(!ownerYard&&!ownerId){const name=$('#aoSearch').value.trim(),phone=$('#nop')?.value.trim(),identityNumber=$('#non')?.value.trim();if(!name||!phone||!identityNumber)throw Error(offlineNewAsset?'بدون إنترنت: أدخل اسم المالك ورقم الهاتف ورقم الهوية قبل الحفظ.':'أدخل اسم المالك ورقم الهاتف ورقم الهوية، أو اختر مالكًا موجودًا من الاقتراحات');if(offlineNewAsset){offlineOwner={name,phone,identityNumber,identityType:$('#noi')?.value||'NATIONAL_ID',clientRequestId:window.__ownerRequestId||(window.__ownerRequestId=crypto.randomUUID())}}else{const ownerClientRequestId=window.__ownerRequestId||(window.__ownerRequestId=crypto.randomUUID());const o=await api('/api/admin/owners',{method:'POST',body:JSON.stringify({name,phone,identityNumber,identityType:$('#noi')?.value||'NATIONAL_ID',clientRequestId:ownerClientRequestId})});ownerId=o.id}}const b={categoryId:$('#ag').value,ownerId,ownerType,yardId:state.yards[0]?.id||'demo-yard',purpose,status:id?($('#as')?.value||'ACTIVE'):'ACTIVE',salePrice:$('#asp')?.value||null,currentBid:$('#acb')?.value||null,rentPrice:$('#arp')?.value||null,rentUnit:$('#aru')?.value||null,dailyStorageFee:$('#adf')?.value||0,make:'',model:customFields.model||'',year:null,color:customFields.color||'',variant:customFields.variant||'',plateNumber:customFields.plateNumber||'',locationCode:$('#al').value,entryAt:$('#ae')?.value?new Date($('#ae').value).toISOString():null,description:$('#ad').value,entryNotes:$('#an').value,customFields};if(!b.ownerId&&!offlineNewAsset)throw Error('اختر مالكًا أو أدخل بيانات مالك جديد');if(purpose==='SALE'){b.rentPrice=null;b.rentUnit=null;b.dailyStorageFee=0}if(purpose==='RENT'){b.salePrice=null}if(purpose==='STORAGE'){b.salePrice=null;b.rentPrice=null;b.rentUnit=null}const clientRequestId=window.__assetRequestId||(window.__assetRequestId=crypto.randomUUID());b.clientRequestId=clientRequestId;const imageFiles=[...($('#ai')?.files||[]),...($('#aiCamera')?.files||[])];if(offlineNewAsset){const images=[];for(const f of imageFiles){images.push(await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error||new Error('تعذر حفظ الصورة محليًا'));r.readAsDataURL(f)}))}const op={id:crypto.randomUUID(),type:'ASSET_CREATE',payload:{...b,ownerId:ownerYard?state.me?.id:null,ownerType,owner:offlineOwner,queuedAt:new Date().toISOString()},images};await queueOfflineOperationAsync(op);closeModal();window.__assetRequestId=null;window.__ownerRequestId=null;alert(`تم حفظ الأصل على الجهاز مؤقتًا بدون إنترنت. ${images.length?'تم حفظ الصور أيضًا وستُرفع تلقائيًا بعد عودة الإنترنت. ':''}سيتم إرسال البيانات تلقائيًا عند عودة الاتصال.`);return}const saved=await api(id?'/api/admin/assets/'+id:'/api/admin/assets',{method:id?'PUT':'POST',body:JSON.stringify(b)});for(const f of imageFiles){const data=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(f)});await api('/api/admin/assets/'+saved.id+'/images',{method:'POST',body:JSON.stringify({dataUrl:data,filename:f.name})})}closeModal();window.__assetRequestId=null;window.__ownerRequestId=null;await dashboard('assets');if(!id)assetReceiptActions(saved);else alert('تم حفظ التعديلات بنجاح')}catch(e){window.__assetSaveBusy=false;if(btn){btn.disabled=false;btn.textContent=id?'حفظ التعديلات':'＋ إضافة الأصل وحفظ';}alert(e.message)}}

function identityTypeName(v){return ({NATIONAL_ID:'هوية وطنية',PERSONAL_ID:'بطاقة شخصية',RESIDENCY_ID:'هوية مقيم',PASSPORT:'جواز سفر',OTHER:'هوية أخرى'})[v]||v||''}
function receiptTypeName(t){return t==='ASSET_ENTRY'?'سند استلام أصل':'سند استلام مبلغ'}
function moneyText(v,currency){return `${money(v)} ${currency||state.settings?.currency||''}`}
async function entryReceipt(id){try{const r=await api(`/api/admin/assets/${id}/receipts/entry`,{method:'POST',body:'{}'});receiptPreview(r,true)}catch(e){alert(e.message)}}
function assetReceiptActions(r){modal(`<h3>تم تسجيل الأصل بنجاح</h3><p class="muted">يمكنك الآن إنشاء سند استلام الأصل وإرساله إلى رقم صاحب المعدة المسجل.</p><div class="toolbar"><button class="btn primary" onclick="entryReceipt('${r.id}')">📄 إنشاء سند استلام الأصل</button><button class="btn" onclick="closeModal()">لاحقًا</button></div>`)}
async function paymentReceiptForm(assetId){modal(`<h3>سند استلام مبلغ</h3><p class="muted">بيانات المالك والأصل تؤخذ تلقائيًا. أدخل بيانات العميل/الدافع فقط.</p><div class="two"><input id="prn" class="input" placeholder="اسم العميل / الدافع"><input id="prp" class="input" placeholder="رقم هاتف العميل / الدافع"></div><div class="two"><input id="pra" class="input" type="number" placeholder="المبلغ"><select id="prt" class="select"><option value="DEPOSIT">عربون حجز</option><option value="PAYMENT">دفعة</option><option value="RENT">إيجار</option><option value="OTHER">أخرى</option></select></div><textarea id="prd" class="input" placeholder="البيان / الملاحظات"></textarea><button class="btn primary" onclick="savePaymentReceipt('${assetId}')">حفظ وإنشاء السند</button>`)}
async function savePaymentReceipt(assetId){try{const r=await api(`/api/admin/assets/${assetId}/receipts/payment`,{method:'POST',body:JSON.stringify({payerName:$('#prn').value,payerPhone:$('#prp').value,amount:$('#pra').value,paymentType:$('#prt').value,description:$('#prd').value})});receiptPreview(r,false)}catch(e){alert(e.message)}}
function receiptPreview(r,isEntry){const url='/receipt.html?id='+encodeURIComponent(r.id);window.location.assign(url)}


async function editAsset(id){assetForm(await api('/api/admin/assets/'+id))}
async function exitAsset(id){const reason=prompt('سبب الخروج: OWNER_PICKUP / SOLD / RENTED / OTHER','OWNER_PICKUP');if(!reason)return;const paid=prompt('المبلغ المدفوع للتخزين إن وجد','0');try{await api('/api/admin/assets/'+id+'/exit',{method:'POST',body:JSON.stringify({reason,paid:Number(paid||0)})});dashboard('assets')}catch(e){alert(e.message)}}
function storagePay(id){modal(`<h3>تسجيل دفعة تخزين</h3><input id="pa" class="input" type="number" placeholder="المبلغ"><br><br><button class="btn primary" onclick="payStorage('${id}')">حفظ</button>`)}async function payStorage(id){try{await api('/api/admin/storage/payment',{method:'POST',body:JSON.stringify({chargeId:id,amount:$('#pa').value})});closeModal();dashboard('storage')}catch(e){alert(e.message)}}
function confirmReservation(id){modal(`<h3>تأكيد الحجز وتسجيل العربون</h3><div class="two"><div class="field"><label>السعر المتفق عليه</label><input id="ra" class="input" type="number"></div><div class="field"><label>العربون المدفوع</label><input id="rd" class="input" type="number"></div></div><div class="field"><label>ملاحظة</label><textarea id="rn2" class="input"></textarea></div><button class="btn primary" onclick="saveReservationConfirm('${id}')">تأكيد وتحويل إلى محجوز</button>`)}
async function saveReservationConfirm(id){try{await api('/api/admin/reservations/'+id,{method:'PUT',body:JSON.stringify({status:'CONFIRMED',agreedAmount:$('#ra').value,depositAmount:$('#rd').value,note:$('#rn2').value})});closeModal();dashboard('reservations')}catch(e){alert(e.message)}}
async function reservationStatus(id,status){if(status==='CONFIRMED')return confirmReservation(id);await api('/api/admin/reservations/'+id,{method:'PUT',body:JSON.stringify({status})});dashboard('reservations')}
async function offerStatus(id,status){if(window.__offerStatusBusy)return;window.__offerStatusBusy=true;try{await api('/api/admin/offers/'+id,{method:'PUT',body:JSON.stringify({status})});await dashboard('offers')}catch(e){alert(e.message)}finally{window.__offerStatusBusy=false}}
function financeForm(){modal(`<h3>حركة مالية</h3><div class="two"><select id="ft" class="select"><option value="INCOME">دخل</option><option value="EXPENSE">مصروف</option></select><input id="fa" class="input" type="number" placeholder="المبلغ"></div><div class="field"><input id="fc" class="input" placeholder="التصنيف"></div><div class="field"><input id="fr" class="input" placeholder="المرجع"></div><div class="field"><textarea id="fd" class="input" placeholder="الوصف"></textarea></div><button class="btn primary" onclick="saveFinance()">حفظ</button>`)}async function saveFinance(){await api('/api/admin/transactions',{method:'POST',body:JSON.stringify({type:$('#ft').value,amount:$('#fa').value,category:$('#fc').value,reference:$('#fr').value,description:$('#fd').value})});closeModal();dashboard('finance')}
function orderForm(){modal(`<h3>تسجيل طلب</h3><div class="two"><input id="ocn" class="input" placeholder="اسم العميل"><input id="ocp" class="input" placeholder="الجوال"></div><div class="two"><select id="oct" class="select"><option value="GENERAL">طلب عام</option><option value="BUY">شراء</option><option value="RENT">إيجار</option><option value="SERVICE">خدمة</option><option value="OTHER">أخرى</option></select><input id="oca" class="input" type="number" placeholder="المبلغ المتوقع (اختياري)"></div><textarea id="ocd" class="input" placeholder="تفاصيل الطلب"></textarea><textarea id="ocn2" class="input" placeholder="ملاحظات"></textarea><button id="orderSaveBtn" class="btn primary" onclick="saveOrder()">حفظ الطلب</button>`)}async function saveOrder(){if(window.__orderBusy)return;window.__orderBusy=true;const btn=$('#orderSaveBtn');if(btn)btn.disabled=true;try{const clientRequestId=window.__orderRequestId||(window.__orderRequestId=crypto.randomUUID());await api('/api/admin/orders',{method:'POST',body:JSON.stringify({customerName:$('#ocn').value,phone:$('#ocp').value,type:$('#oct').value,amount:$('#oca').value,description:$('#ocd').value,notes:$('#ocn2').value,clientRequestId})});window.__orderRequestId=null;closeModal();await dashboard('orders')}catch(e){alert(e.message)}finally{window.__orderBusy=false;if(btn)btn.disabled=false}}async function orderStatus(id,status){try{await api('/api/admin/orders/'+id,{method:'PUT',body:JSON.stringify({status})});await dashboard('orders')}catch(e){alert(e.message)}}
function invoiceForm(){modal(`<h3>إصدار فاتورة</h3><p class="muted">الفاتورة لإثبات مبلغ مستحق على عميل مقابل بيع أو إيجار أو خدمة. أما المشتريات والمقاضي والكفرات ونحوها فتسجل كمصروف في المالية.</p><div class="two"><input id="ipn" class="input" placeholder="اسم العميل / الطرف *"><input id="ipp" class="input" placeholder="الجوال"></div><div class="two"><select id="itype" class="select"><option value="SALE">بيع</option><option value="RENT">إيجار</option><option value="SERVICE">خدمة</option><option value="STORAGE">تخزين / توقيف</option><option value="OTHER">أخرى</option></select><input id="isub" class="input" type="number" min="0" placeholder="الإجمالي قبل الخصم والضريبة"></div><div class="two"><input id="idis" class="input" type="number" placeholder="الخصم"><input id="itax" class="input" type="number" placeholder="الضريبة"></div><div class="two"><input id="ipaid" class="input" type="number" placeholder="المدفوع"><input id="iasset" class="input" placeholder="كود الأصل (اختياري)"></div><textarea id="inotes" class="input" placeholder="بيان الفاتورة / التفاصيل"></textarea><br><br><button class="btn primary" onclick="saveInvoice()">إصدار الفاتورة</button>`)}async function saveInvoice(){if(window.__invoiceBusy)return;window.__invoiceBusy=true;try{await api('/api/admin/invoices',{method:'POST',body:JSON.stringify({type:$('#itype').value,partyName:$('#ipn').value,partyPhone:$('#ipp').value,subtotal:$('#isub').value,discount:$('#idis').value,tax:$('#itax').value,paid:$('#ipaid').value,assetId:$('#iasset').value||null,notes:$('#inotes').value})});closeModal();await dashboard('invoices')}catch(e){alert(e.message)}finally{window.__invoiceBusy=false}}
async function contractForm(){const xs=await api('/api/admin/assets');modal(`<h3>عقد وساطة</h3><div class="field"><label>الأصل</label><select id="cta" class="select">${xs.map(a=>`<option value="${a.id}">${esc(a.title)} — ${a.code}</option>`).join('')}</select></div><div class="two"><input id="ctp" class="input" placeholder="اسم الطرف"><input id="ctph" class="input" placeholder="الجوال"></div><div class="two"><input id="ctam" class="input" type="number" placeholder="قيمة العملية"><select id="cttype" class="select"><option value="FIXED">عمولة ثابتة</option><option value="PERCENT">نسبة مئوية</option></select></div><div class="field"><input id="ctcv" class="input" type="number" placeholder="قيمة العمولة أو النسبة"></div><textarea id="ctterms" class="input" placeholder="الشروط"></textarea><br><br><button class="btn primary" onclick="saveContract()">حفظ</button>`)}async function saveContract(){const percent=$('#cttype').value==='PERCENT';await api('/api/admin/contracts',{method:'POST',body:JSON.stringify({assetId:$('#cta').value,partyName:$('#ctp').value,partyPhone:$('#ctph').value,amount:$('#ctam').value,commissionType:percent?'PERCENT':'FIXED',commissionRate:percent?$('#ctcv').value:0,commissionFixed:percent?0:$('#ctcv').value,terms:$('#ctterms').value})});closeModal();dashboard('contracts')}
function locationForm(){modal(`<h3>موقع داخل الحوش</h3><div class="two"><input id="lc" class="input" placeholder="A-03"><input id="ln" class="input" placeholder="اسم الموقع"></div><input id="lz" class="input" placeholder="المنطقة"><br><br><button class="btn primary" onclick="saveLocation()">حفظ</button>`)}async function saveLocation(){await api('/api/admin/locations',{method:'POST',body:JSON.stringify({code:$('#lc').value,name:$('#ln').value,zone:$('#lz').value,yardId:state.yards[0]?.id})});closeModal();dashboard('locations')}
async function conditionForm(){const xs=await api('/api/admin/assets');modal(`<h3>محضر استلام/تسليم</h3><select id="coa" class="select">${xs.map(a=>`<option value="${a.id}">${esc(a.title)} — ${a.code}</option>`).join('')}</select><br><br><select id="cot" class="select"><option value="ENTRY">دخول</option><option value="EXIT">خروج</option></select><div class="two"><input id="coo" class="input" placeholder="عداد الكيلومترات"><input id="coh" class="input" placeholder="ساعات التشغيل"></div><input id="coc" class="input" placeholder="حالة الأصل بالتفصيل (مثال: جيدة، خدوش بسيطة)" required><input id="coa2" class="input" placeholder="الملحقات"><textarea id="con" class="input" placeholder="الملاحظات"></textarea><br><button class="btn primary" onclick="saveCondition()">حفظ</button>`)}async function saveCondition(){if(window.__conditionBusy)return;window.__conditionBusy=true;try{await api('/api/admin/conditions',{method:'POST',body:JSON.stringify({assetId:$('#coa').value,type:$('#cot').value,odometer:$('#coo').value,engineHours:$('#coh').value,condition:$('#coc').value,accessories:$('#coa2').value,notes:$('#con').value})});closeModal();dashboard('conditions')}catch(e){alert(e.message)}finally{window.__conditionBusy=false}}
async function userForm(id){modal(`<h3>إضافة مستخدم / مالك</h3><div class="two"><input id="un" class="input" placeholder="الاسم"><input id="up" class="input" placeholder="الجوال"></div><div class="two"><select id="ui" class="select"><option value="NATIONAL_ID">هوية وطنية / شخصية</option><option value="RESIDENCY_ID">هوية مقيم</option><option value="PASSPORT">جواز سفر</option><option value="OTHER">هوية أخرى</option></select><input id="uin" class="input" placeholder="رقم الهوية"></div><div class="two"><select id="ur" class="select"><option value="CUSTOMER">عميل</option><option value="RECEPTION">استقبال</option><option value="SALES">مبيعات</option><option value="YARD">مسؤول الحوش</option><option value="ACCOUNTING">محاسبة</option><option value="MANAGER">مدير</option><option value="ADMIN">مدير النظام</option></select><input id="ux" class="input" type="password" placeholder="كلمة المرور"></div><button class="btn primary" onclick="saveUser('${id||''}')">حفظ</button>`)}async function saveUser(id){await api(id?'/api/admin/users/'+id:'/api/admin/users',{method:id?'PUT':'POST',body:JSON.stringify({name:$('#un').value,phone:$('#up').value,identityType:$('#ui').value,identityNumber:$('#uin').value,role:$('#ur').value,password:$('#ux').value})});closeModal();dashboard('users')}
function categoryForm(c={}){modal(`<h3>${c.id?'تعديل تصنيف':'إضافة تصنيف'}</h3><input id="cn" class="input" placeholder="الاسم" value="${esc(c.name)}"><input id="ci" class="input" placeholder="الأيقونة" value="${esc(c.icon||'📦')}"><div class="three"><label><input id="cs" type="checkbox" ${c.allowSale!==false?'checked':''}> بيع</label><label><input id="cr" type="checkbox" ${c.allowRent!==false?'checked':''}> إيجار</label><label><input id="ct" type="checkbox" ${c.allowStorage!==false?'checked':''}> توقيف</label></div><label><input id="ca" type="checkbox" ${c.active!==false?'checked':''}> نشط</label><br><button class="btn primary" onclick="saveCat('${c.id||''}')">حفظ</button>`)}async function saveCat(id){await api(id?'/api/admin/categories/'+id:'/api/admin/categories',{method:id?'PUT':'POST',body:JSON.stringify({name:$('#cn').value,icon:$('#ci').value,allowSale:$('#cs').checked,allowRent:$('#cr').checked,allowStorage:$('#ct').checked,active:$('#ca').checked})});state.cats=await api('/api/categories');closeModal();dashboard('categories')}async function editCategory(id){const xs=await api('/api/admin/categories');categoryForm(xs.find(x=>x.id===id)||{})}
async function saveSettings(){try{const ticker=String($('#stm')?.value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).slice(0,20);await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({name:$('#sn').value,tagline:$('#st').value,country:$('#sco').value,city:$('#sci').value,countryCode:$('#scc').value,whatsapp:$('#sw').value,phone:$('#sp').value,email:$('#se').value,address:$('#sa').value,latitude:$('#sla')?.value||'',longitude:$('#slo')?.value||'',mapsUrl:$('#smu')?.value||'',currency:$('#sc').value,storageDefaultRate:$('#sr').value,ownerName:$('#son')?.value||'أبو مناحي السبيعي',ownerPhone:$('#sop')?.value||'',managerName:$('#smn')?.value||'أبو أنس الإدريسي',managerPhone:$('#smp')?.value||'',developerName:$('#sdn')?.value||'هيثم القاضي',aboutTitle:$('#sat')?.value||'عن حوشك',aboutText:$('#sab')?.value||'',servicesText:$('#ssv')?.value||'',howToText:$('#shu')?.value||'',futureText:$('#sfu')?.value||'',tickerMessages:JSON.stringify(ticker)})});state.settings=await api('/api/public/settings');alert('تم حفظ الإعدادات ومحتوى المنصة');dashboard('settings')}catch(e){alert(e.message)}}
async function report(days){const r=await api('/api/admin/reports/summary?days='+days);$('#report').innerHTML=`<div class="stats"><div class="stat">الدخل<strong>${money(r.income)}</strong></div><div class="stat">المصروف<strong>${money(r.expense)}</strong></div><div class="stat">الصافي<strong>${money(r.net)}</strong></div><div class="stat">الأصول المضافة<strong>${r.assetsAdded}</strong></div><div class="stat">الخروج<strong>${r.exits}</strong></div><div class="stat">متأخرات التخزين<strong>${money(r.storageOutstanding)}</strong></div><div class="stat">متأخرات الفواتير<strong>${money(r.invoiceOutstanding)}</strong></div></div><div class="field-section"><h4>الأصول حسب التصنيف</h4>${Object.entries(r.byCategory||{}).map(([k,v])=>`<div class="audit-item"><strong>${esc(k)}</strong><span>${v} أصل</span></div>`).join('')||'<div class="muted">لا توجد بيانات.</div>'}</div>`}
async function myAssets(){const xs=await api('/api/my/assets');document.querySelector('#app').innerHTML=shell(`<main class="container"><div class="panel"><h2>أصولي</h2>${xs.length?`<table><tr><th>الأصل</th><th>الكود</th><th>الغرض</th><th>الحالة</th><th>التخزين</th></tr>${xs.map(a=>`<tr><td>${esc(a.title)}</td><td>${a.code}</td><td>${purposeName(a.purpose)}</td><td>${statusName(a.status)}</td><td>${a.storage?.current?money(a.storage.current):'-'}</td></tr>`).join('')}</table>`:'<div class="empty">لا توجد أصول مرتبطة بحسابك.</div>'}</div></main>`)}
async function reply(id){const b=prompt('اكتب الرد');if(b){await api('/api/admin/inquiries/'+id+'/messages',{method:'POST',body:JSON.stringify({body:b})});dashboard('inquiries')}}
async function exportDb(){const d=await api('/api/admin/export');const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='system-backup.json';a.click()}
(async()=>{try{await init()}catch(e){document.querySelector('#app').innerHTML=`<div class="container"><div class="notice">${esc(e.message)}</div></div>`}})();
